import{_ as t,o as n,c as e,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Daftar Saran Pengaturan Perluasan","description":"","frontmatter":{},"headers":[],"relativePath":"id/0098-扩展设定建议清单.md","filePath":"id/0098-扩展设定建议清单.md"}'),r={name:"id/0098-扩展设定建议清单.md"};function s(u,a,d,k,o,m){return n(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="daftar-saran-pengaturan-perluasan" tabindex="-1">Daftar Saran Pengaturan Perluasan <a class="header-anchor" href="#daftar-saran-pengaturan-perluasan" aria-label="Permalink to &quot;Daftar Saran Pengaturan Perluasan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>98</td></tr><tr><td>Modul</td><td>Lampiran dan Materi Referensi</td></tr><tr><td>Kata Kunci Utama</td><td>pengaturan perluasan, saran kreatif, arah pengaturan, keterbukaan, bidang yang belum dikembangkan</td></tr></tbody></table><h2 id="_1-deskripsi" tabindex="-1">1. Deskripsi <a class="header-anchor" href="#_1-deskripsi" aria-label="Permalink to &quot;1. Deskripsi&quot;">​</a></h2><p>Dokumen ini mencantumkan arah dan saran yang tersedia untuk kreasi perluasan dalam sistem pengaturan Peradaban Simbiosis Jangkar, bertujuan untuk memberikan inspirasi dan panduan kepada pencipta pengaturan, membantu mereka melakukan perluasan pengaturan yang berharga dalam kerangka yang ada. Daftar ini diklasifikasikan menurut modul, dan setiap arah perluasan mencakup deskripsi arah, nilai perluasan, hubungan dengan pengaturan yang ada, dan saran kreatif. Perlu ditekankan bahwa daftar ini hanyalah referensi saran; pencipta dapat berkreasi secara bebas dengan syarat mengikuti konsistensi pengaturan, atau dapat mengembangkan arah baru yang tidak tercakup dalam daftar ini. Semua pengaturan perluasan harus lulus pemeriksaan Dokumen 97 &quot;Tabel Pemeriksaan Mandiri Kontradiksi Pengaturan&quot; sebelum secara resmi dimasukkan.</p><h2 id="_2-arah-perluasan-pandangan-dunia-dan-pengaturan-inti" tabindex="-1">2. Arah Perluasan Pandangan Dunia dan Pengaturan Inti <a class="header-anchor" href="#_2-arah-perluasan-pandangan-dunia-dan-pengaturan-inti" aria-label="Permalink to &quot;2. Arah Perluasan Pandangan Dunia dan Pengaturan Inti&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E01</td><td>Keberadaan di luar batas alam semesta</td><td>Menjelajahi apakah ada alam semesta lain atau keberadaan dimensi yang lebih tinggi di luar jaringan hukum Hengyuanzhou, memberikan pandangan alam semesta yang lebih megah untuk pengaturan</td><td>Dokumen 00, Dokumen 28</td><td>Dapat mengatur keberadaan &quot;dinding alam semesta&quot; dan cerita beberapa penjelajah yang menembus dinding alam semesta, meninggalkan petunjuk untuk interaksi antar alam semesta di masa depan</td></tr><tr><td>E02</td><td>Esensi kehendak alam semesta</td><td>Membahas secara mendalam apakah ada &quot;kehendak alam semesta&quot; di lapisan bawah jaringan hukum dan hubungannya dengan mekanisme jangkar</td><td>Dokumen 00, Dokumen 20</td><td>Dapat mengatur kehendak alam semesta sebagai fenomena pengorganisasian diri hukum yang non-personal, bukan dewa tertentu, mempertahankan posisi &quot;berbasis realitas&quot;</td></tr><tr><td>E03</td><td>Peradaban yang hilang dari era pra-jangkar</td><td>Mengatur secara rinci peradaban yang pernah makmur tetapi telah punah di era pra-jangkar, memperkaya kedalaman sejarah</td><td>Dokumen 71, Dokumen 93</td><td>Dapat mengatur 3-5 peradaban yang hilang yang representatif, setiap peradaban memiliki sistem kultivasi, budaya, dan alasan kepunahan yang unik, memberikan bahan untuk pengaturan arkeologi</td></tr><tr><td>E04</td><td>Aliran filsafat konsep simbiosis</td><td>Di bawah kerangka besar &quot;anti-penjarahan, advokasi simbiosis&quot;, mengatur interpretasi berbeda dari berbagai aliran filsafat terhadap konsep simbiosis</td><td>Dokumen 04, Dokumen 03</td><td>Dapat mengatur aliran seperti &quot;aliran simbiosis radikal&quot;, &quot;aliran simbiosis moderat&quot;, &quot;aliran simbiosis ekologis&quot;, &quot;aliran simbiosis teknologi&quot;, dan pertarungan ideologis di antara mereka dapat menjadi ketegangan alur cerita yang penting</td></tr></tbody></table><h2 id="_3-arah-perluasan-sistem-kultivasi" tabindex="-1">3. Arah Perluasan Sistem Kultivasi <a class="header-anchor" href="#_3-arah-perluasan-sistem-kultivasi" aria-label="Permalink to &quot;3. Arah Perluasan Sistem Kultivasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E05</td><td>Metode rinci dari satu sistem</td><td>Memperluas secara rinci salah satu dari tiga ratus sistem, termasuk metode kultivasi spesifik, metode terobosan alam, kesalahan umum, dll.</td><td>Dokumen 10-19, Dokumen 91</td><td>Disarankan untuk memprioritaskan perluasan tiga dasar fundamental dan sistem dalam kategori teknik terapan yang terkait erat dengan teknologi; dokumen rinci setiap sistem dapat mencakup langkah kultivasi, formula mental, kebutuhan sumber daya, peringatan risiko, dll.</td></tr><tr><td>E06</td><td>Rencana kombinasi kultivasi simultan sistem</td><td>Meneliti kompatibilitas kultivasi simultan antar sistem yang berbeda dan merancang rencana kombinasi multi-sistem yang optimal</td><td>Dokumen 10, Dokumen 11-13</td><td>Dapat mengatur &quot;kombinasi emas&quot; (seperti iterasi deduksi + hukum ruang + teknik terapan) dan berbagai kombinasi tidak lazim, menganalisis keuntungan dan keterbatasan setiap kombinasi</td></tr><tr><td>E07</td><td>Hambatan kultivasi dan metode terobosan</td><td>Mengatur secara rinci hambatan yang mungkin dihadapi setiap sistem di alam yang berbeda dan berbagai metode terobosan hambatan</td><td>Dokumen 14, Dokumen 19</td><td>Dapat mengatur berbagai jenis hambatan seperti &quot;tribulasi iblis batin&quot;, &quot;penghalang hukum&quot;, &quot;obstruksi asal&quot;, dan jalur terobosan yang sesuai, meningkatkan hierarki proses kultivasi</td></tr><tr><td>E08</td><td>Konstitusi khusus dan adaptasi sistem</td><td>Mengatur berbagai konstitusi khusus (seperti konstitusi dao bawaan, tubuh afinitas elemen, tubuh sensitivitas kesadaran, dll.) dan hubungan adaptasinya dengan sistem kultivasi yang berbeda</td><td>Dokumen 12, Dokumen 51</td><td>Dapat merancang &quot;matriks adaptasi konstitusi-sistem&quot; untuk membantu pencipta dengan cepat menilai sistem mana yang cocok untuk konstitusi tertentu</td></tr><tr><td>E09</td><td>Klasifikasi rinci sumber daya kultivasi</td><td>Mengklasifikasikan dan mengatur secara rinci berbagai sumber daya yang dibutuhkan untuk kultivasi (harta karun alam, kristal energi, fragmen hukum, dll.)</td><td>Dokumen 18, Dokumen 65</td><td>Dapat mengatur tingkat, tempat produksi, metode pengumpulan, metode penyimpanan, larangan penggunaan sumber daya, dll., membangun ekosistem sumber daya kultivasi yang lengkap</td></tr></tbody></table><h2 id="_4-arah-perluasan-sistem-sosial" tabindex="-1">4. Arah Perluasan Sistem Sosial <a class="header-anchor" href="#_4-arah-perluasan-sistem-sosial" aria-label="Permalink to &quot;4. Arah Perluasan Sistem Sosial&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E10</td><td>Bentuk sosial spesifik dari lima jenis</td><td>Memperluas secara rinci sistem sosial spesifik, model ekonomi, dan karakteristik budaya dari masing-masing lima jenis peradaban simbiosis</td><td>Dokumen 30-35</td><td>Setiap jenis dapat mengatur bentuk kota khas, struktur keluarga, model pendidikan, perayaan festival, dll., membuat lima jenis memiliki karakteristik masing-masing</td></tr><tr><td>E11</td><td>Perencanaan dan pembangunan kota simbiosis</td><td>Mengatur konsep perencanaan, gaya arsitektur, infrastruktur, dan pembagian fungsi kota dalam peradaban simbiosis</td><td>Dokumen 39, Dokumen 60</td><td>Dapat merancang berbagai jenis bentuk kota seperti &quot;kota simbiosis vertikal&quot;, &quot;kota bersarang ekologis&quot;, &quot;kota lipat ruang&quot;</td></tr><tr><td>E12</td><td>Operasi rinci sistem pendidikan</td><td>Mengatur secara rinci mekanisme operasi lengkap sistem pendidikan simbiosis, dari pendidikan prasekolah hingga pendidikan tinggi dan pendidikan kultivasi</td><td>Dokumen 37, Dokumen 43</td><td>Dapat mengatur sistem kurikulum, metode penilaian, sistem mentor, rencana pendidikan antar ras, dll.</td></tr><tr><td>E13</td><td>Operasi rinci sistem medis</td><td>Mengatur secara rinci mekanisme operasi sistem medis simbiosis, termasuk kombinasi medis konvensional dan medis kultivasi</td><td>Dokumen 38, Dokumen 44</td><td>Dapat mengatur sistem rumah sakit, proses penggantian asuransi medis, norma khusus perawatan kultivasi, rencana medis antar ras, dll.</td></tr><tr><td>E14</td><td>Jaminan sosial dan sistem kesejahteraan</td><td>Mengatur secara rinci sistem jaminan sosial peradaban simbiosis, termasuk pensiun, pengangguran, bantuan, dll.</td><td>Dokumen 32, Dokumen 08</td><td>Dapat mengatur syarat pengajuan kesejahteraan, standar distribusi, sumber pendanaan, mekanisme pengawasan, dll.</td></tr></tbody></table><h2 id="_5-arah-perluasan-hukum-dan-tata-kelola" tabindex="-1">5. Arah Perluasan Hukum dan Tata Kelola <a class="header-anchor" href="#_5-arah-perluasan-hukum-dan-tata-kelola" aria-label="Permalink to &quot;5. Arah Perluasan Hukum dan Tata Kelola&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E15</td><td>Kasus hukum khas</td><td>Menulis kasus khas yang diadili oleh Pengadilan Simbiosis, menunjukkan penerapan praktis hukum</td><td>Dokumen 40-49, Dokumen 92</td><td>Dapat menulis kasus representatif seperti &quot;kasus monopoli sumber daya kultivasi&quot;, &quot;kasus ganti rugi polusi antar bidang&quot;, &quot;kasus hak tubuh pengganti gelap&quot;</td></tr><tr><td>E16</td><td>Sistem otonomi lokal</td><td>Mengatur secara rinci sistem otonomi dan pembagian kekuasaan setiap wilayah bintang dan setiap bidang dalam kerangka konstitusi</td><td>Dokumen 40, Dokumen 49</td><td>Dapat mengatur model otonomi unit otonom yang berbeda, hubungan dengan pemerintah pusat, proses penyusunan peraturan otonomi, dll.</td></tr><tr><td>E17</td><td>Sistem pemilihan dan demokrasi</td><td>Mengatur secara rinci sistem pemilihan perwakilan Dewan Jangkar dan mekanisme pengambilan keputusan demokratis</td><td>Dokumen 32, Dokumen 49</td><td>Dapat mengatur pembagian daerah pemilihan, kualifikasi calon, proses pemilihan, metode pemungutan suara, sistem masa jabatan, dll.</td></tr><tr><td>E18</td><td>Mekanisme penegakan hukum</td><td>Mengatur secara rinci mekanisme penegakan hukum, termasuk lembaga penegak hukum, proses penegakan, tindakan paksa</td><td>Dokumen 48, Dokumen 49</td><td>Dapat mengatur struktur organisasi lembaga penegak hukum, wewenang penegakan, proses penegakan, mekanisme pengawasan, dll.</td></tr></tbody></table><h2 id="_6-arah-perluasan-kehidupan-dan-ras" tabindex="-1">6. Arah Perluasan Kehidupan dan Ras <a class="header-anchor" href="#_6-arah-perluasan-kehidupan-dan-ras" aria-label="Permalink to &quot;6. Arah Perluasan Kehidupan dan Ras&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E19</td><td>Pengaturan rinci satu ras</td><td>Memperluas secara rinci salah satu ras dari Katalog Semua Ras, termasuk karakteristik fisiologis, struktur sosial, tradisi budaya, evolusi sejarah</td><td>Dokumen 50-52, Dokumen 94</td><td>Disarankan untuk memprioritaskan perluasan ras khas seperti ras naga, ras peri, ras mekanik, ras makhluk sadar; setiap ras dapat mencakup bahasa, agama, seni, adat istiadat, dll.</td></tr><tr><td>E20</td><td>Kasus spesifik kehidupan aneh</td><td>Mengatur individu atau kelompok kehidupan aneh yang spesifik, menunjukkan penerapan praktis dari tiga jenis proses penanganan</td><td>Dokumen 53-54</td><td>Dapat mengatur kasus kehidupan aneh seperti &quot;penghanyut kekosongan&quot;, &quot;kehidupan fragmen waktu&quot;, &quot;parasit hukum&quot;</td></tr><tr><td>E21</td><td>Jenis spesifik energi aneh</td><td>Mengatur secara rinci karakteristik, sumber, kegunaan, dan metode kontrol berbagai energi aneh</td><td>Dokumen 55-56</td><td>Dapat mengatur jenis energi aneh seperti &quot;energi kausal&quot;, &quot;energi kesadaran&quot;, &quot;energi gema waktu&quot;</td></tr><tr><td>E22</td><td>Kasus spesifik tubuh pengganti gelap</td><td>Mengatur cerita individu spesifik tubuh pengganti gelap, menunjukkan penerapan praktis etika jiwa ganda dan empat jenis penanganan cabang</td><td>Dokumen 57-59</td><td>Dapat menulis cerita kasus berbagai jenis tubuh pengganti gelap, mengeksplorasi dilema etika koeksistensi jiwa ganda</td></tr><tr><td>E23</td><td>Keturunan fusi antar ras</td><td>Mengatur karakteristik dan budaya ras campuran yang dihasilkan dari pernikahan antar ras yang berbeda</td><td>Dokumen 52, Dokumen 77</td><td>Dapat mengatur ras campuran seperti &quot;setengah peri&quot;, &quot;manusia naga&quot;, &quot;biomekanik&quot;, mengeksplorasi identitas dan fusi budaya mereka</td></tr></tbody></table><h2 id="_7-arah-perluasan-teknologi-dan-energi" tabindex="-1">7. Arah Perluasan Teknologi dan Energi <a class="header-anchor" href="#_7-arah-perluasan-teknologi-dan-energi" aria-label="Permalink to &quot;7. Arah Perluasan Teknologi dan Energi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E24</td><td>Prinsip rinci satu teknologi</td><td>Menganalisis secara rinci prinsip satu teknologi kunci (seperti cermin salin, ruang terisolasi, rekayasa buah Bei Zeng)</td><td>Dokumen 60-69, Dokumen 63-64</td><td>Dapat mengatur sejarah pengembangan teknologi, komponen inti, alur kerja, keterbatasan teknologi, arah pembaruan, dll.</td></tr><tr><td>E25</td><td>Klasifikasi rinci instrumen kultivasi</td><td>Mengatur klasifikasi, fungsi, tingkat, dan metode penggunaan berbagai instrumen bantu kultivasi</td><td>Dokumen 61, Dokumen 67</td><td>Dapat mengatur jenis instrumen seperti &quot;kapsul kultivasi&quot;, &quot;detektor hukum&quot;, &quot;konverter energi&quot;, &quot;penguat kesadaran&quot;</td></tr><tr><td>E26</td><td>Pengaturan rinci perangkat keras jangkar</td><td>Mengatur secara rinci struktur, fungsi, pembangunan, dan pemeliharaan fasilitas perangkat keras jangkar</td><td>Dokumen 20, Dokumen 67</td><td>Dapat mengatur komponen inti jangkar buatan, pasokan energi, siklus pemeliharaan, penanganan kegagalan, dll.</td></tr><tr><td>E27</td><td>Teknologi komunikasi antar bidang</td><td>Mengatur secara rinci prinsip teknologi, jenis perangkat, protokol komunikasi, dan mekanisme keamanan komunikasi antar bidang</td><td>Dokumen 66, Dokumen 81</td><td>Dapat mengatur berbagai metode komunikasi seperti &quot;komunikasi gelombang jangkar&quot;, &quot;komunikasi lipat ruang&quot;, &quot;komunikasi resonansi kesadaran&quot;</td></tr></tbody></table><h2 id="_8-arah-perluasan-sejarah-dan-peristiwa" tabindex="-1">8. Arah Perluasan Sejarah dan Peristiwa <a class="header-anchor" href="#_8-arah-perluasan-sejarah-dan-peristiwa" aria-label="Permalink to &quot;8. Arah Perluasan Sejarah dan Peristiwa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E28</td><td>Narasi rinci peristiwa sejarah penting</td><td>Narasi sejarah rinci dari satu peristiwa penting dalam kronik</td><td>Dokumen 70-79, Dokumen 93</td><td>Dapat menceritakan secara rinci seluruh proses peristiwa seperti &quot;peristiwa pembukaan tiga ratus sistem&quot;, &quot;implementasi strategi aktivasi 20%&quot;, &quot;tonggak kenaikan dimensi pertama&quot;</td></tr><tr><td>E29</td><td>Biografi tokoh sejarah</td><td>Menulis biografi rinci untuk tokoh kunci, memperkaya kedalaman manusiawi sejarah</td><td>Dokumen 95</td><td>Dapat menulis biografi untuk tokoh kunci seperti &quot;Xuan Hengzi&quot;, &quot;Gongshengzi&quot;, &quot;Lixiangong&quot;, &quot;Sanbaishi&quot;</td></tr><tr><td>E30</td><td>Analisis hipotetis titik balik sejarah</td><td>Menganalisis bagaimana perkembangan peradaban simbiosis akan berbeda jika satu peristiwa sejarah berjalan berbeda</td><td>Dokumen 70-79</td><td>Dapat melakukan analisis hipotetis seperti &quot;jika konstitusi simbiosis tidak disahkan&quot;, &quot;jika strategi aktivasi 20% gagal&quot;, menunjukkan kontingensi sejarah</td></tr><tr><td>E31</td><td>Catatan rinci penemuan arkeologi</td><td>Mengatur penemuan rinci dan hasil penelitian dari satu arkeologi antar bidang</td><td>Dokumen 84-87</td><td>Dapat mengatur seperti &quot;penemuan arkeologi satu peradaban yang hilang&quot;, &quot;hasil arkeologi mundur waktu satu simpul sejarah kunci&quot;</td></tr></tbody></table><h2 id="_9-arah-perluasan-antar-bidang-dan-waktu" tabindex="-1">9. Arah Perluasan Antar Bidang dan Waktu <a class="header-anchor" href="#_9-arah-perluasan-antar-bidang-dan-waktu" aria-label="Permalink to &quot;9. Arah Perluasan Antar Bidang dan Waktu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nomor</th><th>Arah Perluasan</th><th>Nilai Perluasan</th><th>Pengaturan Terkait</th><th>Saran Kreatif</th></tr></thead><tbody><tr><td>E32</td><td>Pengaturan rinci satu bidang spesifik</td><td>Mengatur parameter hukum, bentuk peradaban, lingkungan geografis, dan sejarah dari satu bidang spesifik</td><td>Dokumen 80, Dokumen 81</td><td>Dapat mengatur berbagai jenis bidang spesifik seperti &quot;bidang sihir tinggi&quot;, &quot;bidang teknologi&quot;, &quot;bidang liar&quot;, &quot;bidang kesadaran&quot;</td></tr><tr><td>E33</td><td>Kasus diplomasi antar bidang</td><td>Mengatur kasus spesifik pembentukan hubungan diplomatik antara peradaban simbiosis dan peradaban bidang lainnya</td><td>Dokumen 81, Dokumen 88</td><td>Dapat mengatur peristiwa diplomatik spesifik seperti kontak pertama, negosiasi pembentukan hubungan, pertukaran budaya, perjanjian perdagangan</td></tr><tr><td>E34</td><td>Kasus spesifik mundur waktu</td><td>Mengatur proses spesifik, penemuan, dan dampak dari satu operasi mundur waktu</td><td>Dokumen 82-83, Dokumen 89</td><td>Dapat mengatur kasus seperti &quot;pemecahan mundur satu misteri sejarah&quot;, &quot;pemulihan mundur satu peradaban yang punah&quot;</td></tr><tr><td>E35</td><td>Catatan rinci peristiwa paradoks waktu</td><td>Mengatur seluruh proses terjadinya, respons darurat, dan perbaikan kausal dari satu peristiwa paradoks waktu</td><td>Dokumen 89</td><td>Dapat menulis catatan penanganan lengkap dari satu peristiwa paradoks skala kecil, menunjukkan operasi praktis mekanisme pencegahan dan kontrol</td></tr><tr><td>E36</td><td>Konflik dan resolusi antar bidang</td><td>Mengatur konflik antara peradaban simbiosis dan peradaban bidang lainnya serta proses resolusi damai mereka</td><td>Dokumen 81, Dokumen 88</td><td>Dapat mengatur berbagai jenis kasus konflik antar bidang seperti sengketa sumber daya, konflik budaya, sengketa perbatasan</td></tr></tbody></table><h2 id="_10-prinsip-kreatif-pengaturan-perluasan" tabindex="-1">10. Prinsip Kreatif Pengaturan Perluasan <a class="header-anchor" href="#_10-prinsip-kreatif-pengaturan-perluasan" aria-label="Permalink to &quot;10. Prinsip Kreatif Pengaturan Perluasan&quot;">​</a></h2><p>Saat melakukan kreasi pengaturan perluasan, prinsip-prinsip berikut harus diikuti:</p><ol><li><strong>Konsistensi优先</strong>: Semua pengaturan perluasan harus menjaga konsistensi logis dengan pengaturan yang ada, dan lulus pemeriksaan tabel pemeriksaan mandiri kontradiksi pengaturan.</li><li><strong>Berbasis realitas</strong>: Pengaturan perluasan harus didasarkan pada hukum objektif untuk deduksi yang wajar, menghindari fantasi murni dan keruntuhan pengaturan.</li><li><strong>Posisi simbiosis</strong>: Pengaturan perluasan harus selalu mempertahankan posisi inti anti-penjarahan dan advokasi simbiosis, tidak boleh membela perilaku penjarahan.</li><li><strong>Keterbukaan</strong>: Pengaturan perluasan harus mempertahankan tingkat keterbukaan tertentu, menyisakan ruang untuk perluasan lebih lanjut di masa depan.</li><li><strong>Kepraktisan</strong>: Pengaturan perluasan harus memiliki nilai kreatif praktis, mampu memberikan bahan yang berguna untuk kreasi cerita, desain game, dan diskusi teoretis.</li></ol><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Daftar Saran Pengaturan Perluasan adalah &quot;pintu terbuka&quot; dari sistem pengaturan Peradaban Simbiosis Jangkar. Ini menunjukkan bahwa sistem pengaturan ini bukanlah produk tertutup dan lengkap, melainkan sistem hidup yang terus tumbuh dan terus diperkaya. Tiga puluh enam arah perluasan hanyalah titik awal; kreativitas pengaturan yang sebenarnya berasal dari imajinasi dan antusiasme setiap peserta. Selama prinsip dasar konsistensi pengaturan diikuti, setiap perluasan yang berharga akan menjadi bagian yang sangat diperlukan dari narasi megah Peradaban Simbiosis Jangkar.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>97-Tabel Pemeriksaan Mandiri Kontradiksi Pengaturan</li><li>99-Instruksi Versi dan Pemeliharaan Dokumen</li><li>96-Pertanyaan yang Sering Diajukan FAQ</li></ul>',27)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
